Tìm số đo ${x}$ trong hình sau. 

\choice
{  $x={76}^{\circ}$ }
   { $x={81}^{\circ}$  }
     { \True $x={71}^{\circ}$  }
    { $x={70}^{\circ}$ }
}{
\begin{tikzpicture}
        % Các điểm
        \coordinate (N) at (0, 4);
        \coordinate (P) at (6, 4);
        \coordinate (M) at (1, 0);
        \coordinate (Q) at (5, 0);

        % Các cạnh của hình thang
        \draw (N) -- (P) -- (Q) -- (M) -- cycle;

        % Ghi giá trị góc
        \node at (1.5, 0.4) {$109^\circ$};
        \node at (4.6, 0.4) {$109^\circ$};
        \node at (0.4, 3.7) {$x$};
        \node at (5.5, 3.7) {$x$};

        % Ghi tên các đỉnh
        \node[above left] at (N) {$N$};
        \node[above right] at (P) {$P$};
        \node[below left] at (M) {$M$};
        \node[below right] at (Q) {$Q$};
    \end{tikzpicture}
}
\loigiai{
Trong tứ giác $MNPQ$, tổng bốn góc bằng $360^\circ$ nên $x + x + 109^\circ + 109^\circ = 360^\circ \Rightarrow 2x = 142^\circ \Rightarrow x = 71^\circ$.
}\end{ex}

